```javascript
// Enhanced application with proper error handling, input validation, and security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');
const cors = require('cors');
const { validationResult, body, param, query } = require('express-validator');
const logger = require('./logger'); // Assuming you have a logger utility

const app = express();

// Security middleware
app.use(helmet()); // Set security HTTP headers
app.use(express.json({ limit: '10kb' })); // Limit JSON body size
app.use(express.urlencoded({ extended: true, limit: '10kb' })); // Limit URL-encoded data

// Prevent NoSQL injection
app.use(mongoSanitize());

// Prevent XSS attacks
app.use(xss());

// Prevent HTTP parameter pollution
app.use(hpp());

// Enable CORS with restricted origins (configure as needed)
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// Request logging
app.use((req, res, next) => {
  logger.info(`${req.method} ${req.path}`, {
    ip: req.ip,
    userAgent: req.get('User-Agent'),
    timestamp: new Date().toISOString()
  });
  next();
});

// Health check endpoint with validation
app.get('/health', 
  [
    // Validate query parameters if any are expected
    query('detailed').optional().isBoolean()
  ],
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        error: 'Validation failed', 
        details: errors.array() 
      });
    }

    const detailed = req.query.detailed === 'true';
    const response = {
      status: 'ok',
      timestamp: new Date().toISOString()
    };

    if (detailed) {
      response.uptime = process.uptime();
      response.memoryUsage = process.memoryUsage();
    }

    res.json(response);
  }
);

// Users endpoint with proper validation and error handling
app.get('/users', 
  [
    // Validate and sanitize query parameters
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .toInt(),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .toInt(),
    query('sort')
      .optional()
      .isIn(['id', 'name', 'email'])
  ],
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        error: 'Validation failed', 
        details: errors.array() 
      });
    }

    try {
      // Simulate users data (in real app, this would come from database)
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
        { id: 3, name: 'Charlie', email: 'charlie@example.com' }
      ];

      // Apply pagination if specified
      const limit = req.query.limit || users.length;
      const offset = req.query.offset || 0;
      const paginatedUsers = users.slice(offset, offset + limit);

      // Apply sorting if specified
      if (req.query.sort) {
        paginatedUsers.sort((a, b) => {
          if (a[req.query.sort] < b[req.query.sort]) return -1;
          if (a[req.query.sort] > b[req.query.sort]) return 1;
          return 0;
        });
      }

      res.json({
        data: paginatedUsers,
        pagination: {
          limit,
          offset,
          total: users.length
        }
      });
    } catch (error) {
      // Log the error for debugging
      logger.error('Error fetching users:', error);

      // Return generic error message to client (don't expose internal details)
      res.status(500).json({ 
        error: 'Internal server error' 
      });
    }
  }
);

// Example POST endpoint with comprehensive validation
app.post('/users',
  [
    // Validate and sanitize request body
    body('name')
      .trim()
      .notEmpty()
      .withMessage('Name is required')
      .isLength({ min: 2, max: 50 })
      .withMessage('Name must be between 2 and 50 characters')
      .matches(/^[a-zA-Z\s]+$/)
      .withMessage('Name can only contain letters and spaces'),
    body('email')
      .trim()
      .notEmpty()
      .withMessage('Email is required')
      .isEmail()
      .withMessage('Please provide a valid email address')
      .normalizeEmail(),
    body('age')
      .optional()
      .isInt({ min: 0, max: 150 })
      .withMessage('Age must be a number between 0 and 150')
  ],
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        error: 'Validation failed', 
        details: errors.array() 
      });
    }

    try {
      // In a real application, you would save the user to the database here
      const newUser = {
        id: Date.now(), // Simple ID generation (use proper UUID/db sequence in production)
        ...req.body
      };

      // Log successful user creation
      logger.info('User created successfully', { userId: newUser.id, email: newUser.email });

      res.status(201).json({
        message: 'User created successfully',
        data: newUser
      });
    } catch (error) {
      logger.error('Error creating user:', error);
      res.status(500).json({ 
        error: 'Internal server error' 
      });
    }
  }
);

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({ 
    error: 'Route not found' 
  });
});

// Global error handling middleware
app.use((err, req, res, next) => {
  // Log the error for debugging (in production, be careful about what you log)
  logger.error(`Global error: ${err.message}`, {
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    url: req.originalUrl,
    method: req.method,
    ip: req.ip
  });

  // Determine status code
  const statusCode = err.statusCode || 500;

  // In production, don't send detailed error messages to the client
  const errorResponse = process.env.NODE_ENV === 'production' && statusCode >= 500
    ? { error: 'Internal server error' }
    : { 
        error: err.message || 'Internal server error',
        // Include stack trace only in development
        ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
      };

  res.status(statusCode).json(errorResponse);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  logger.error('Unhandled Rejection at:', Promise, 'reason:', reason);
  // Application specific logging, throwing an error, or other logic here
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  logger.error('Uncaught Exception thrown:', err);
  process.exit(1);
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM received, shutting down gracefully');
  server.close(() => {
    logger.info('Process terminated');
  });
});

module.exports = app;
```

### Key Security Improvements Made:

1. **Input Validation & Sanitization**:
   - Used `express-validator` for comprehensive input validation
   - Added sanitization to prevent XSS and injection attacks
   - Implemented specific validation rules for each endpoint

2. **Security Middleware**:
   - Added `helmet()` for security HTTP headers
   - Implemented rate limiting to prevent brute force attacks
   - Added CORS with configurable origins
   - Included protection against NoSQL injection, XSS, and HTTP parameter pollution

3. **Error Handling**:
   - Added comprehensive error handling middleware
   - Implemented specific error handling for validation errors
   - Added 404 handler for undefined routes
   - Included global error handler that doesn't leak sensitive info in production
   - Added process-level error handlers for unhandled rejections and exceptions

4. **Logging & Monitoring**:
   - Added request logging for security monitoring
   - Implemented proper error logging without exposing sensitive data
   - Included graceful shutdown handling

5. **Additional Security Measures**:
   - Limited request payload sizes
   - Added timeout protection (would need timeout middleware)
   - Environment-based error responses (detailed in dev, generic in prod)
   - Input normalization and trimming

### Additional Recommendations:

1. **Dependencies**: Make sure to install required packages:
   ```
   npm install express helmet express-rate-limit xss-clean express-mongo-sanitize hpp cors express-validator
   ```

2. **Environment Configuration**: Use environment variables for:
   - Port configuration
   - Allowed origins for CORS
   - Rate limit configurations
   - Logging levels

3. **Further Enhancements**:
   - Add request timeout middleware
   - Implement API versioning
   - Add API documentation (Swagger/OpenAPI)
   - Implement authentication and authorization
   - Add database connection pooling and error handling
   - Implement request ID tracking for distributed tracing

These improvements follow security best practices including the principle of least privilege, defense in depth, secure defaults, and fail-safe error handling. The validation and sanitization help prevent common web vulnerabilities like injection attacks, XSS, and parameter pollution.

