// Enhanced application with improved error handling, input validation, and security practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');
const AppError = require('./utils/appError');
const globalErrorHandler = require('./controllers/errorController');
const logger = require('./utils/logger');

const app = express();

// Security Middleware
app.use(helmet()); // Set security HTTP headers

// Prevent JSON injection and NoSQL injection
app.use(express.json({ limit: '10kb' }));
app.use(mongoSanitize());

// Prevent XSS attacks
app.use(xss());

// Prevent HTTP Parameter Pollution
app.use(hpp());

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  max: 100,
  windowMs: 60 * 60 * 1000, // 1 hour
  message: 'Too many requests from this IP, please try again in an hour!'
});
app.use('/api/', limiter);

// Body parser, reading data from body into req.body
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Test middleware for logging requests
app.use((req, res, next) => {
  logger.info(`${req.method} ${req.url}`);
  req.requestTime = new Date().toISOString();
  next();
});

// Health check endpoint with proper error handling
app.get('/health', (req, res, next) => {
  try {
    res.status(200).json({
      status: 'success',
      data: {
        status: 'ok',
        timestamp: req.requestTime
      }
    });
  } catch (err) {
    next(err);
  }
});

// Users endpoint with input validation and error handling
app.get('/users', (req, res, next) => {
  try {
    // Validate query parameters if any
    const { limit, page } = req.query;

    // Input validation with sane defaults
    const parsedLimit = Math.min(parseInt(limit) || 10, 100); // Max 100 items
    const parsedPage = Math.max(parseInt(page) || 1, 1); // Min page 1

    // Simulate database query with validation
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination if needed
    const startIndex = (parsedPage - 1) * parsedLimit;
    const endIndex = startIndex + parsedLimit;
    const paginatedUsers = users.slice(startIndex, endIndex);

    res.status(200).json({
      status: 'success',
      results: paginatedUsers.length,
      data: {
        users: paginatedUsers,
        pagination: {
          page: parsedPage,
          limit: parsedLimit,
          total: users.length
        }
      }
    });
  } catch (err) {
    next(new AppError('Failed to retrieve users', 500));
  }
});

// Handle undefined routes
app.all('*', (req, res, next) => {
  next(new AppError(`Can't find ${req.originalUrl} on this server!`, 404));
});

// Global error handling middleware
app.use(globalErrorHandler);

module.exports = app;

// Custom error class for operational errors
class AppError extends Error {
  constructor(message, statusCode) {
    super(message);

    this.statusCode = statusCode;
    this.status = `${statusCode}`.startsWith('4') ? 'fail' : 'error';
    this.isOperational = true;

    Error.captureStackTrace(this, this.constructor);
  }
}

module.exports = AppError;

// Global error handling controller
const AppError = require('../utils/appError');
const logger = require('../utils/logger');

const sendErrorDev = (err, req, res) => {
  // Log error for development
  logger.error(`${err.statusCode} - ${err.message}\n${err.stack}`);

  res.status(err.statusCode).json({
    status: err.status,
    error: err,
    message: err.message,
    stack: err.stack
  });
};

const sendErrorProd = (err, req, res) => {
  // Operational, trusted error: send message to client
  if (err.isOperational) {
    logger.warn(`${err.statusCode} - ${err.message}`);

    res.status(err.statusCode).json({
      status: err.status,
      message: err.message
    });
  } else {
    // Programming or other unknown error: don't leak error details
    logger.error(`${err.statusCode} - Error: ${err.message}\n${err.stack}`);

    // Send generic message
    res.status(500).json({
      status: 'error',
      message: 'Something went very wrong!'
    });
  }
};

// Handle specific errors
const handleCastErrorDB = err => {
  const message = `Invalid ${err.path}: ${err.value}.`;
  return new AppError(message, 400);
};

const handleDuplicateFieldsDB = err => {
  const value = err.errmsg.match(/(["'])(\\?.)*?\1/)[0];
  const message = `Duplicate field value: ${value}. Please use another value!`;
  return new AppError(message, 400);
};

const handleValidationErrorDB = err => {
  const errors = Object.values(err.errors).map(el => el.message);
  const message = `Invalid input data. ${errors.join('. ')}`;
  return new AppError(message, 400);
};

const handleJWTError = () =>
  new AppError('Invalid token. Please log in again!', 401);

const handleJWTExpiredError = () =>
  new AppError('Your token has expired! Please log in again.', 401);

module.exports = (err, req, res, next) => {
  // Set defaults
  err.statusCode = err.statusCode || 500;
  err.status = err.status || 'error';

  // Log all errors
  logger.error(`${err.statusCode} - ${err.message}`);

  if (process.env.NODE_ENV === 'development') {
    sendErrorDev(err, req, res);
  } else if (process.env.NODE_ENV === 'production') {
    let error = { ...err };
    error.message = err.message;

    // Handle specific error types
    if (error.name === 'CastError') error = handleCastErrorDB(error);
    if (error.code === 11000) error = handleDuplicateFieldsDB(error);
    if (error.name === 'ValidationError')
      error = handleValidationErrorDB(error);
    if (error.name === 'JsonWebTokenError') error = handleJWTError();
    if (error.name === 'TokenExpiredError') error = handleJWTExpiredError();

    sendErrorProd(error, req, res);
  }
};

// Simple logger utility
const { createLogger, format, transports } = require('winston');
const { combine, timestamp, label, printf } = format;

const logger = createLogger({
  level: process.env.NODE_ENV === 'production' ? 'info' : 'debug',
  format: combine(
    label({ label: 'right-meow!' }),
    timestamp(),
    printf(
      info => `${info.timestamp} [${info.label}] ${info.level}: ${info.message}`
    )
  ),
  transports: [
    new transports.Console(),
    new transports.File({ filename: 'error.log', level: 'error' }),
    new transports.File({ filename: 'combined.log' })
  ]
});

module.exports = logger;

