// Improved application with enhanced error handling and security

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { celebrate, Joi, errors } = require('celebrate');
const app = express();

// Security middleware
app.use(helmet()); // Sets various HTTP headers for security
app.use(express.json()); // Parse JSON bodies

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});
app.use(limiter);

// Health check endpoint with validation
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users endpoint with input validation and error handling
app.get(
  '/users',
  celebrate({
    query: Joi.object({
      limit: Joi.number().integer().min(1).max(100).default(10),
      offset: Joi.number().integer().min(0).default(0),
      search: Joi.string().max(50).allow('', null),
      sort: Joi.string().valid('name', 'email', 'id').default('id'),
      order: Joi.string().valid('asc', 'desc').default('asc'),
    }),
  }),
  (req, res) => {
    try {
      // Mock user data - in real app, this would come from a database
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
        { id: 3, name: 'Charlie', email: 'charlie@example.com' },
        { id: 4, name: 'Diana', email: 'diana@example.com' },
        { id: 5, name: 'Eve', email: 'eve@example.com' },
      ];

      // Apply search filter if provided
      let filteredUsers = users;
      if (req.query.search) {
        const searchTerm = req.query.search.toLowerCase();
        filteredUsers = users.filter(
          user =>
            user.name.toLowerCase().includes(searchTerm) ||
            user.email.toLowerCase().includes(searchTerm)
        );
      }

      // Apply sorting
      filteredUsers.sort((a, b) => {
        if (a[req.query.sort] < b[req.query.sort]) return req.query.order === 'asc' ? -1 : 1;
        if (a[req.query.sort] > b[req.query.sort]) return req.query.order === 'asc' ? 1 : -1;
        return 0;
      });

      // Apply pagination
      const paginatedUsers = filteredUsers.slice(
        req.query.offset,
        req.query.offset + req.query.limit
      );

      res.json({
        data: paginatedUsers,
        pagination: {
          limit: req.query.limit,
          offset: req.query.offset,
          total: filteredUsers.length,
          returned: paginatedUsers.length,
        },
      });
    } catch (error) {
      // Handle unexpected errors
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// Error handling middleware
app.use(errors()); // Celebrate error handler for validation errors

app.use((err, req, res, next) => {
  // Log error for debugging (in production, use proper logging)
  console.error(err);

  // Handle validation errors from celebrate
  if (err.isJoi) {
    return res.status(400).json({
      error: 'Validation failed',
      details: err.details.map(detail => detail.message),
    });
  }

  // Handle other errors
  res.status(err.status || 500).json({
    error: err.message || 'Internal server error',
    // In production, don't expose internal error details
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack }),
  });
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

