const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');
const app = express();

// Security middleware
app.use(helmet()); // Set security HTTP headers
app.use(xss()); // Sanitize user input from XSS
app.use(mongoSanitize()); // Prevent NoSQL injection
app.use(hpp()); // Prevent parameter pollution

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});
app.use(limiter);

// Body parsing middleware
app.use(express.json({ limit: '10kb' })); // Limit JSON body size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Custom request logging middleware
app.use((req, res, next) => {
  console.log(`${req.method} ${req.path} - ${new Date().toISOString()}`);
  next();
});

// Input validation middleware for query parameters
const validateQueryParams = (req, res, next) => {
  // Validate and sanitize query parameters
  if (req.query.limit && (!Number.isInteger(Number(req.query.limit)) || Number(req.query.limit) < 1 || Number(req.query.limit) > 100)) {
    return res.status(400).json({ 
      error: 'Bad Request', 
      message: 'Limit parameter must be a number between 1 and 100' 
    });
  }

  if (req.query.offset && (!Number.isInteger(Number(req.query.offset)) || Number(req.query.offset) < 0)) {
    return res.status(400).json({ 
      error: 'Bad Request', 
      message: 'Offset parameter must be a non-negative number' 
    });
  }

  next();
};

// Health check endpoint with improved error handling
app.get('/health', validateQueryParams, (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(500).json({ 
      error: 'Internal Server Error', 
      message: 'Unable to retrieve health status' 
    });
  }
});

// Users endpoint with improved error handling and validation
app.get('/users', validateQueryParams, (req, res) => {
  try {
    // In a real application, this would come from a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination if limit and offset are provided
    let filteredUsers = users;
    if (req.query.limit !== undefined || req.query.offset !== undefined) {
      const limit = Number(req.query.limit) || users.length;
      const offset = Number(req.query.offset) || 0;
      filteredUsers = users.slice(offset, offset + limit);
    }

    res.json({
      data: filteredUsers,
      pagination: {
        limit: Number(req.query.limit) || users.length,
        offset: Number(req.query.offset) || 0,
        total: users.length
      }
    });
  } catch (error) {
    console.error('Error in /users endpoint:', error);
    res.status(500).json({ 
      error: 'Internal Server Error', 
      message: 'Unable to retrieve users' 
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({ 
    error: 'Not Found', 
    message: `Route ${req.originalUrl} not found` 
  });
});

// Centralized error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Determine status code based on error type
  const statusCode = err.status || 500;

  // Don't leak stack trace in production
  const response = {
    error: statusCode === 500 ? 'Internal Server Error' : err.message || 'Unknown Error',
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack })
  };

  res.status(statusCode).json(response);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // Application specific logging, throwing an error, or other logic here
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception thrown');
  process.exit(1);
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = app;

