// Improved application with better error handling, input validation, and security practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');
const cors = require('cors');

const app = express();

// Security Middleware
app.use(helmet()); // Set security HTTP headers
app.use(cors()); // Enable CORS
app.use(express.json({ limit: '10kb' })); // Body parser with size limit
app.use(xss()); // Data sanitization against XSS
app.use(mongoSanitize()); // Data sanitization against NoSQL injection
app.use(hpp()); // Prevent parameter pollution

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// Health check endpoint with better error handling
app.get('/health', (req, res, next) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    next(error); // Pass error to error handling middleware
  }
});

// Users endpoint with input validation
app.get('/users', (req, res, next) => {
  try {
    // Validate query parameters if any were expected
    const { limit, offset } = req.query;

    // Validate limit and offset if provided
    if (limit !== undefined && (isNaN(limit) || parseInt(limit) < 1 || parseInt(limit) > 100)) {
      return res.status(400).json({
        error: 'Validation failed',
        message: 'Limit must be a number between 1 and 100'
      });
    }

    if (offset !== undefined && (isNaN(offset) || parseInt(offset) < 0)) {
      return res.status(400).json({
        error: 'Validation failed',
        message: 'Offset must be a non-negative number'
      });
    }

    // Mock users data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' }
    ];

    // Apply pagination if requested
    const limitNum = limit ? parseInt(limit) : users.length;
    const offsetNum = offset ? parseInt(offset) : 0;

    const paginatedUsers = users.slice(offsetNum, offsetNum + limitNum);

    res.json({
      count: paginatedUsers.length,
      total: users.length,
      users: paginatedUsers
    });
  } catch (error) {
    next(error); // Pass error to error handling middleware
  }
});

// 404 handler for undefined routes
app.use('*', (req, res, next) => {
  res.status(404).json({
    error: 'Not found',
    message: `Can't find ${req.originalUrl} on this server!`
  });
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err); // Log error for debugging

  // Set default status code and message
  let statusCode = err.statusCode || 500;
  let message = err.message || 'Internal Server Error';

  // Don't leak stack trace in production
  if (process.env.NODE_ENV === 'production') {
    // Hide sensitive error details
    message = statusCode === 500 ? 'Internal Server Error' : message;
  } else {
    // Include stack trace in development
    res.locals.error = err;
  }

  res.status(statusCode).json({
    error: message,
    // Only include stack in development
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack })
  });
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  console.error('UNHANDLED REJECTION! 💥 Shutting down...');
  console.error(err.name, err.message);
  server.close(() => {
    process.exit(1);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('UNCAUGHT EXCEPTION! 💥 Shutting down...');
  console.error(err.name, err.message);
  process.exit(1);
});

module.exports = app;

