  celebrate({
    query: Joi.object({
      detailed: Joi.boolean().optional()
    })
  }),
  (req, res) => {
    try {
      const response = {
        status: 'ok',
        timestamp: new Date().toISOString(),
        uptime: process.uptime()
      };

      if (req.query.detailed) {
        response.memoryUsage = process.memoryUsage();
        response.nodeVersion = process.version;
      }

      res.json(response);
    } catch (error) {
      logger.error('Health check failed:', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

// Users endpoint with proper validation and error handling
app.get('/users',
  celebrate({
    query: Joi.object({
      page: Joi.number().integer().min(1).default(1),
      limit: Joi.number().integer().min(1).max(100).default(10),
      sort: Joi.string().valid('name', 'email', 'id').optional(),
      search: Joi.string().max(50).optional().allow('')
    })
  }),
  (req, res) => {
    try {
      // In a real app, this would come from a database
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply filtering based on validated query params
      let filteredUsers = [...users];

      if (req.query.search) {
        const searchTerm = req.query.search.toLowerCase();
        filteredUsers = filteredUsers.filter(user =>
          user.name.toLowerCase().includes(searchTerm) ||
          user.email.toLowerCase().includes(searchTerm)
        );
      }

      // Apply sorting
      if (req.query.sort) {
        filteredUsers.sort((a, b) => {
          if (a[req.query.sort] < b[req.query.sort]) return -1;
          if (a[req.query.sort] > b[req.query.sort]) return 1;
          return 0;
        });
      }

      // Apply pagination
      const page = parseInt(req.query.page);
      const limit = parseInt(req.query.limit);
      const startIndex = (page - 1) * limit;
      const endIndex = page * limit;

      const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

      res.json({
        success: true,
        count: paginatedUsers.length,
        pagination: {
          page,
          limit,
          totalPages: Math.ceil(filteredUsers.length / limit),
          totalItems: filteredUsers.length
        },
        data: paginatedUsers
      });
    } catch (error) {
      logger.error('Error in users endpoint:', error);
      res.status(500).json({
        success: false,
        error: 'Internal server error'
      });
    }
  }
);

