// Enhanced application with security best practices for error handling and input validation
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');
const app = express();

// Security middleware - Essential for protecting against common vulnerabilities
app.use(helmet()); // Set security HTTP headers
app.use(express.json({ limit: '10kb' })); // Body parser with size limit to prevent payload attacks
app.use(urlencoded({ extended: true, limit: '10kb' })); // Parse URL-encoded bodies
app.use(xss()); // Prevent XSS attacks
app.use(mongoSanitize()); // Prevent NoSQL injection
app.use(hpp()); // Prevent HTTP parameter pollution

// Rate limiting to prevent DoS and brute-force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});
app.use(limiter);

// Request logging for security monitoring and audit trails
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.path} - IP: ${req.ip || req.connection.remoteAddress}`);
  next();
});

// Health check endpoint with comprehensive error handling
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memoryUsage: process.memoryUsage()
    });
  } catch (error) {
    // Log the error for internal monitoring but don't expose details to client
    console.error('Health check error:', error);
    res.status(500).json({ 
      status: 'error', 
      message: 'Internal server error' 
    });
  }
});

// Users endpoint with robust input validation, sanitization, and error handling
app.get('/users', (req, res) => {
  try {
    // === INPUT VALIDATION AND SANITIZATION ===

    // Parse and validate limit parameter
    let limit = parseInt(req.query.limit);
    if (isNaN(limit)) {
      limit = 10; // Default value
    } else {
      // Ensure limit is within safe bounds
      limit = Math.max(1, Math.min(limit, 100)); // Between 1 and 100
    }

    // Parse and validate offset parameter
    let offset = parseInt(req.query.offset);
    if (isNaN(offset)) {
      offset = 0; // Default value
    } else {
      // Ensure offset is non-negative
      offset = Math.max(0, offset);
    }

    // Optional: Validate search parameter if provided
    let searchTerm = null;
    if (req.query.search) {
      searchTerm = String(req.query.search).trim();
      // Reject empty search terms or excessively long ones
      if (searchTerm.length === 0 || searchTerm.length > 100) {
        return res.status(400).json({ 
          error: 'Invalid search parameter',
          message: 'Search term must be between 1 and 100 characters' 
        });
      }
      // Basic sanitization - remove potential script tags (additional to xss-clean)
      searchTerm = searchTerm.replace(/<[^>]*>/g, '');
    }

    // === SIMULATED DATA ACCESS WITH ERROR HANDLING ===
    // In a real application, this would be a database call

    // Simulate potential database connectivity issues
    const simulateDbError = Math.random() < 0.01; // 1% chance of simulated error
    if (simulateDbError) {
      throw new Error('Database connection temporarily unavailable');
    }

    // Sample data - in reality, this would come from a database
    const allUsers = [
      { id: 1, name: 'Alice Smith', email: 'alice@example.com', role: 'admin' },
      { id: 2, name: 'Bob Jones', email: 'bob@example.com', role: 'user' },
      { id: 3, name: 'Charlie Brown', email: 'charlie@example.com', role: 'user' },
      { id: 4, name: 'Diana Prince', email: 'diana@example.com', role: 'manager' },
      { id: 5, name: 'Edward Wilson', email: 'edward@example.com', role: 'user' }
    ];

    // Apply search filter if search term provided
    let filteredUsers = allUsers;
    if (searchTerm) {
      const lowerSearchTerm = searchTerm.toLowerCase();
      filteredUsers = allUsers.filter(user => 
        user.name.toLowerCase().includes(lowerSearchTerm) || 
        user.email.toLowerCase().includes(lowerSearchTerm)
      );
    }

    // Apply pagination
    const startIndex = offset;
    const endIndex = Math.min(offset + limit, filteredUsers.length);
    const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

    // Remove sensitive fields before sending response (defense in depth)
    const sanitizedUsers = paginatedUsers.map(({ password, ...user }) => user);

    res.json({
      data: sanitizedUsers,
      pagination: {
        limit: limit,
        offset: offset,
        total: filteredUsers.length,
        count: paginatedUsers.length,
        hasMore: (offset + limit) < filteredUsers.length,
        searchApplied: !!searchTerm
      }
    });

  } catch (error) {
    // === CENTRALIZED ERROR HANDLING ===
    // Log full error details for internal monitoring
    console.error('Users endpoint error:', {
      error: error.message,
      stack: process.env.NODE_ENV === 'development' ? error.stack : undefined,
      timestamp: new Date().toISOString(),
      path: req.path,
      query: req.query
    });

    // Determine appropriate HTTP status code based on error type
    let statusCode = 500;
    let errorMessage = 'Internal server error';

    if (error.message.includes('Database connection')) {
      statusCode = 503; // Service Unavailable
      errorMessage = 'Service temporarily unavailable, please try again later';
    } else if (error.message.includes('validation')) {
      statusCode = 400; // Bad Request
      errorMessage = error.message; // Safe to expose validation errors
    }

    // Never expose internal error details to clients in production
    res.status(statusCode).json({ 
      error: errorMessage,
      // Only include detailed error info in development
      ...(process.env.NODE_ENV === 'development' && { 
        debug: error.message,
        timestamp: new Date().toISOString()
      })
    });
  }
});

// 404 handler for undefined routes
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not found',
    message: `Cannot ${req.method} ${req.path}` 
  });
});

// Centralized error handling middleware
app.use((err, req, res, next) => {
  // Log error for monitoring (never log sensitive data)
  console.error('Global error handler:', {
    message: err.message,
    // Only log stack in development
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack }),
    url: req.originalUrl,
    method: req.method,
    ip: req.ip || req.connection.remoteAddress
  });

  // Set default error status and message
  const statusCode = err.status || 500;
  const message = err.status ? err.message : 'Internal server error';

  res.status(statusCode).json({ 
    error: message,
    // Include additional debug info only in development
    ...(process.env.NODE_ENV === 'development' && { 
      stack: err.stack,
      url: req.originalUrl
    })
  });
});

// Graceful shutdown handling
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Handle process termination signals for graceful shutdown
const gracefulShutdown = () => {
  console.log('Received shutdown signal, closing server...');
  server.close(async (err) => {
    if (err) {
      console.error('Error during shutdown:', err);
      process.exit(1);
    }
    console.log('Server closed successfully');
    process.exit(0);
  });

  // Force shutdown after 10 seconds if still open
  setTimeout(() => {
    console.log('Forcing shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Promise Rejection:', {
    reason: reason.message || reason,
    // Avoid logging full promise object which might contain sensitive data
    timestamp: new Date().toISOString()
  });
  // Note: In a real app, you might want to trigger graceful shutdown here
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    timestamp: new Date().toISOString()
  });
  // Trigger graceful shutdown
  gracefulShutdown();
});

module.exports = app;

