// Improved application with enhanced error handling, input validation, and security
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');
const cors = require('cors');
const { celebrate, Joi, errors, Segments } = require('celebrate');
const winston = require('winston');

// Configure Winston logger
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  defaultMeta: { service: 'user-api' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

// Add console output in development
if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

const app = express();

// Security Middleware
app.use(helmet()); // Secure HTTP headers
app.use(cors()); // Enable CORS
app.use(express.json({ limit: '10kb' })); // Body parser with size limit
app.use(express.urlencoded({ extended: true, limit: '10kb' }));
app.use(xss()); // Sanitize against XSS
app.use(mongoSanitize()); // Prevent NoSQL injection
app.use(hpp()); // Prevent HTTP parameter pollution

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests from this IP, please try again later.' }
});
app.use(limiter);

// Request logging middleware
app.use((req, res, next) => {
  logger.info(`${req.method} ${req.path}`, {
    ip: req.ip,
    query: req.query,
    userAgent: req.get('User-Agent')
  });
  next();
});

// Health check endpoint with validation
app.get('/health', 
  celebrate({
    [Segments.QUERY]: Joi.object({
      detailed: Joi.boolean().optional(),
      timestamp: Joi.boolean().optional()
    })
  }),
  (req, res) => {
    try {
      const response = { status: 'ok' };

      if (req.query.timestamp !== false) {
        response.timestamp = new Date().toISOString();
      }

      if (req.query.detailed) {
        response.uptime = process.uptime();
        response.memory = process.memoryUsage();
      }

      res.json(response);
    } catch (error) {
      logger.error('Health check error:', { error: error.message });
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

// Users endpoint with validation and error handling
app.get('/users', 
  celebrate({
    [Segments.QUERY]: Joi.object({
      limit: Joi.number().integer().min(1).max(100).optional().default(10),
      offset: Joi.number().integer().min(0).optional().default(0),
      sort: Joi.string().valid('name', 'email', 'id').optional(),
      search: Joi.string().max(50).optional().allow('')
    })
  }),
  (req, res) => {
    try {
      // Mock user data (in real app, this would come from database)
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
        { id: 3, name: 'Charlie', email: 'charlie@example.com' },
        { id: 4, name: 'Diana', email: 'diana@example.com' },
        { id: 5, name: 'Eve', email: 'eve@example.com' }
      ];

      // Apply search filter if provided
      let filteredUsers = users;
      if (req.query.search) {
        const searchTerm = req.query.search.toLowerCase();
        filteredUsers = users.filter(user => 
          user.name.toLowerCase().includes(searchTerm) || 
          user.email.toLowerCase().includes(searchTerm)
        );
      }

      // Apply sorting if provided
      if (req.query.sort) {
        filteredUsers.sort((a, b) => {
          if (a[req.query.sort] < b[req.query.sort]) return -1;
          if (a[req.query.sort] > b[req.query.sort]) return 1;
          return 0;
        });
      }

      // Apply pagination
      const limit = parseInt(req.query.limit);
      const offset = parseInt(req.query.offset);
      const paginatedUsers = filteredUsers.slice(offset, offset + limit);

      res.json({
        count: filteredUsers.length,
        limit,
        offset,
        users: paginatedUsers
      });
    } catch (error) {
      logger.error('Users endpoint error:', { error: error.message, query: req.query });
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

// 404 handler
app.use('*', (req, res) => {
  logger.warn(`404 - ${req.method} ${req.path} not found`, { ip: req.ip });
  res.status(404).json({ error: 'Not found' });
});

// Error handler middleware (must be last)
app.use(errors()); // Celebrate error handler

app.use((err, req, res, next) => {
  // Log all errors
  logger.error('Unhandled error:', {
    error: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  // Don't leak error details in production
  if (process.env.NODE_ENV === 'production') {
    res.status(err.status || 500).json({
      error: err.message || 'Internal server error'
    });
  } else {
    res.status(err.status || 500).json({
      error: err.message || 'Internal server error',
      stack: err.stack
    });
  }
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM received, shutting down gracefully');
  server.close(() => {
    logger.info('Process terminated');
  });
});

const server = app.listen(3000, () => {
  logger.info('Server running on port 3000');
});

module.exports = app;

