// Improved application with security-focused error handling and input validation

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { validate } = require('express-validation');
const Joi = require('joi');

const app = express();

// Security middleware
app.use(helmet());
app.use(express.json());

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Input validation schemas
const healthCheckSchema = {
  query: Joi.object({
    // No query parameters expected for health check
  })
};

const usersQuerySchema = {
  query: Joi.object({
    limit: Joi.number().integer().min(1).max(100).default(10),
    offset: Joi.number().integer().min(0).default(0),
    search: Joi.string().max(100).allow('')
  })
};

// Health check endpoint with validation
app.get('/health', validate(healthCheckSchema), (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    // Log error for security monitoring
    console.error('Health check error:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      timestamp: new Date().toISOString()
    });
  }
});

// Users endpoint with validation and error handling
app.get('/users', validate(usersQuerySchema), (req, res) => {
  try {
    // Sanitize and validate inputs
    const { limit, offset, search } = req.query;

    // Mock user data - in real app, this would come from database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' },
    ];

    // Apply search filter if provided
    let filteredUsers = users;
    if (search) {
      const sanitizedSearch = search.trim();
      filteredUsers = users.filter(user => 
        user.name.toLowerCase().includes(sanitizedSearch.toLowerCase()) ||
        user.email.toLowerCase().includes(sanitizedSearch.toLowerCase())
      );
    }

    // Apply pagination
    const paginatedUsers = filteredUsers.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        limit,
        offset,
        total: filteredUsers.length,
        returned: paginatedUsers.length
      },
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    // Log error for security monitoring
    console.error('Users endpoint error:', error);

    // Don't expose internal error details to clients
    res.status(500).json({ 
      error: 'Internal server error',
      timestamp: new Date().toISOString()
    });
  }
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not found',
    timestamp: new Date().toISOString()
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Global error handler:', err);

  // Handle validation errors specifically
  if (err.isJoi) {
    return res.status(400).json({ 
      error: 'Validation failed',
      details: err.details.map(detail => detail.message),
      timestamp: new Date().toISOString()
    });
  }

  // Handle express-validation errors
  if (err.status && err.message) {
    return res.status(err.status).json({
      error: err.message,
      timestamp: new Date().toISOString()
    });
  }

  // Generic error response - don't leak internal details
  res.status(500).json({
    error: 'Internal server error',
    timestamp: new Date().toISOString()
  });
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

