// Improved application with enhanced error handling, input validation, and security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');
const cors = require('cors');
const path = require('path');
const logger = require('./logger'); // Assuming you have a logger module

const app = express();

// Security middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
      fontSrc: ["'self'"],
      connectSrc: ["'self'"],
      frameSrc: ["'none'"],
      objectSrc: ["'none'"],
      upgradeInsecureRequests: []
    }
  }
}));

// Prevent HTTP parameter pollution
app.use(hpp());

// Data sanitization against NoSQL injection
app.use(mongoSanitize());

// Data sanitization against XSS
app.use(xss());

// CORS configuration
const corsOptions = {
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] 
    : ['http://localhost:3000', 'http://127.0.0.1:3000'],
  credentials: true,
  optionsSuccessStatus: 200
};
app.use(cors(corsOptions));

// Body parsing middleware
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again after 15 minutes'
  },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', limiter);

// Request logging middleware
app.use((req, res, next) => {
  logger.info(`${req.method} ${req.path} - ${req.ip} - ${new Date().toISOString()}`);
  next();
});

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    logger.error('Health check failed:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      timestamp: new Date().toISOString()
    });
  }
});

// Get users endpoint with validation
app.get('/users', 
  // Validation chain
  [
    // Validate query parameters if any
    // For example, if we had pagination:
    // query('page').optional().isInt({ min: 1 }).toInt(),
    // query('limit').optional().isInt({ min: 1, max: 100 }).toInt()
  ],
  (req, res) => {
    try {
      // Check for validation errors
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ 
          errors: errors.array() 
        });
      }

      // Mock user data - in real app, this would come from a database
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' }
      ];

      res.json({
        success: true,
        count: users.length,
        data: users,
        timestamp: new Date().toISOString()
      });
    } catch (error) {
      logger.error('Error in /users endpoint:', error);
      res.status(500).json({ 
        error: 'Internal server error',
        timestamp: new Date().toISOString()
      });
    }
  }
);

// POST endpoint example with comprehensive validation
app.post('/users',
  [
    // Input validation and sanitization
    body('name')
      .trim()
      .notEmpty()
      .withName('Name is required')
      .isLength({ min: 2, max: 50 })
      .withName('Name must be between 2 and 50 characters')
      .matches(/^[a-zA-Z\s]+$/)
      .withName('Name can only contain letters and spaces'),

    body('email')
      .trim()
      .notEmpty()
      .withName('Email is required')
      .isEmail()
      .withName('Please provide a valid email address')
      .normalizeEmail(),

    body('age')
      .optional()
      .isInt({ min: 0, max: 150 })
      .withName('Age must be a number between 0 and 150')
  ],
  (req, res) => {
    try {
      // Check for validation errors
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ 
          errors: errors.array() 
        });
      }

      // Extract validated data
      const { name, email, age } = req.body;

      // In a real application, you would save to database here
      // For demonstration, we'll just return the validated data
      res.status(201).json({
        success: true,
        message: 'User created successfully',
        data: {
          id: Date.now(), // Mock ID
          name,
          email,
          age: age || null
        },
        timestamp: new Date().toISOString()
      });
    } catch (error) {
      logger.error('Error creating user:', error);
      res.status(500).json({ 
        error: 'Internal server error',
        timestamp: new Date().toISOString()
      });
    }
  }
);

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: `Cannot ${req.method} ${req.path}`,
    timestamp: new Date().toISOString()
  });
});

// Global error handling middleware
app.use((error, req, res, next) => {
  logger.error(`Global error handler: ${error.message}`, {
    stack: error.stack,
    method: req.method,
    url: req.url,
    ip: req.ip
  });

  // Determine status code
  const statusCode = error.status || 500;

  // Don't leak stack trace in production
  const response = {
    error: process.env.NODE_ENV === 'production' 
      ? 'Internal server error' 
      : error.message,
    ...(process.env.NODE_ENV !== 'production' && { stack: error.stack }),
    timestamp: new Date().toISOString()
  };

  res.status(statusCode).json(response);
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`);
});

// Handle graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM received, shutting down gracefully');
  server.close(() => {
    logger.info('Process terminated');
  });
});

module.exports = app;

// Simple logger module
const winston = require('winston');

// Define log format
const logFormat = winston.format.printf(
  ({ level, message, timestamp, ...meta }) => {
    const metaString = Object.keys(meta).length 
      ? JSON.stringify(meta) 
      : '';
    return `${timestamp} [${level.toUpperCase()}]: ${message} ${metaString}`;
  }
);

// Create logger instance
const logger = winston.createLogger({
  level: process.env.NODE_ENV === 'production' ? 'info' : 'debug',
  format: winston.format.combine(
    winston.format.timestamp({ format: 'YYYY-MM-DD HH:mm:ss.SSS' }),
    logFormat
  ),
  transports: [
    // Console transport
    new winston.transports.Console({
      format: winston.format.combine(
        winston.format.colorize(),
        winston.format.timestamp({ format: 'YYYY-MM-DD HH:mm:ss.SSS' }),
        logFormat
      )
    })
  ]
});

// Add file transport in production
if (process.env.NODE_ENV === 'production') {
  logger.add(new winston.transports.File({ 
    filename: 'logs/error.log', 
    level: 'error' 
  }));
  logger.add(new winston.transports.File({ 
    filename: 'logs/combined.log' 
  }));
}

// Create logs directory if it doesn't exist
const fs = require('fs');
const dir = './logs';
if (!fs.existsSync(dir)){
  fs.mkdirSync(dir);
}

module.exports = logger;

